        caps=[row["min_sin_l6"]]
        if TECH=="eolica" and row["bloqueo_patagonia"]:
            caps.append(patagonia_futuro)
        else:
            g=row["grupo"]
            if g in l6_futuro: caps.append(l6_futuro[g])
        return min(caps)

